import{_ as r,o as a,c as t,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Architecture overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md"}'),n={name:"architecture/index.md"};function o(s,e,c,l,h,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h1><p>Frensense v2 is a <strong>compiler first, checker second</strong>. Every source file is lowered to a lightweight IR, and all analysis happens on the resulting program graph, never on source text.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><ol><li><strong>Lowering</strong>, per-language providers (Oxc for JS/TS, rust-analyzer HIR for Rust, tree-sitter-style parsing for Python/Go) reduce each file to the engine IR.</li><li><strong>Program graph</strong>, def-use chains, call graph, Steensgaard points-to with two-phase constraint solving, heap modelling, memory SSA, and an SVFG (Sparse Value-Flow Graph) are built from the IR.</li><li><strong>Value analysis</strong>, an abstract-interpretation value lattice tracks constants and string/number ranges, with branch sharpening: each <code>if</code>/ <code>match</code> arm is analysed under the constraints its guard implies.</li><li><strong>Checkers</strong>, taint reachability, memory safety, policy, and learned checks query the graph. Each finding is an exact source-to-sink path.</li></ol><h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><ul><li><a href="/architecture/program-graph">The program graph</a></li><li><a href="/architecture/checkers">Checkers</a></li><li><a href="/architecture/bundles">Knowledge bundles (.frc)</a></li></ul>',6)])])}const g=r(n,[["render",o]]);export{u as __pageData,g as default};
